{
  "name": "Dressler CESAR 1312 射频电源",
  "name_en": "Dressler CESAR 1312 RF Generator",
  "manufacturer": "Dressler",
  "description": "这是一台可控射频电源/射频发生器，用于向实验装置或其他射频负载提供稳定的射频功率。设备支持设定输出功率、切换控制与调节模式，并可监测反射功率，以帮助评估负载匹配和运行状态。",
  "description_en": "This is a controllable RF power supply / RF generator used to deliver stable radio-frequency power to laboratory equipment or other RF loads. It supports setting output power, selecting control and regulation modes, and monitoring reflected power to help assess load matching and operating condition.",
  "tag_hints": [
    "RF generator",
    "RF power supply",
    "radio-frequency excitation",
    "power regulation",
    "reflected power monitoring",
    "RS-232 instrument"
  ],
  "actions": [
    {
      "action_name": "auto-address",
      "description": "获取/设置设备通信地址",
      "description_en": "Get/set the device communication address."
    },
    {
      "action_name": "auto-control_mode",
      "description": "获取/设置射频发生器的控制模式",
      "description_en": "Get/set the RF generator control mode."
    },
    {
      "action_name": "auto-output_power",
      "description": "获取/设置射频输出功率",
      "description_en": "Get/set the RF output power."
    },
    {
      "action_name": "auto-query",
      "description": "向设备发送数据包并读取响应",
      "description_en": "Send a packet to the device and read back the response."
    },
    {
      "action_name": "auto-regulation_mode",
      "description": "获取/设置功率调节模式",
      "description_en": "Get/set the power regulation mode."
    },
    {
      "action_name": "auto-retries",
      "description": "获取/设置命令失败后的重试次数",
      "description_en": "Get/set the number of retries after a command failure."
    },
    {
      "action_name": "auto-rf",
      "description": "获取/设置射频输出开关状态",
      "description_en": "Get/set the RF output on/off state."
    },
    {
      "action_name": "auto-sendcmd",
      "description": "向设备发送命令包",
      "description_en": "Send a command packet to the device."
    },
    {
      "action_name": "auto-name",
      "description": "获取设备型号/类型名称",
      "description_en": "Get the device model/type name."
    },
    {
      "action_name": "auto-reflected_power",
      "description": "获取反射功率",
      "description_en": "Get the reflected power."
    }
  ]
}

